package com.mindbridge.agent.security;

import com.mindbridge.agent.domain.*;
import com.mindbridge.agent.repository.*;
import com.mindbridge.agent.config.MindBridgeProperties;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.Instant;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.*;
import org.springframework.web.server.*;
import org.springframework.core.env.Environment;

@Service
public class AccountAuthService {
 public static final String COOKIE="solace_session";
 private final UserAccountRepository users; private final AuthRecordRepository records; private final PasswordEncoder encoder;
 private final JavaMailSender mail; private final MindBridgeProperties properties; private final Environment env; private final TransactionTemplate tx;
 private final SecureRandom random=new SecureRandom(); private final String dummy;
 public AccountAuthService(UserAccountRepository users,AuthRecordRepository records,PasswordEncoder encoder,JavaMailSender mail,MindBridgeProperties properties,PlatformTransactionManager manager,Environment env){this.users=users;this.records=records;this.encoder=encoder;this.mail=mail;this.properties=properties;this.env=env;tx=new TransactionTemplate(manager);dummy=encoder.encode(UUID.randomUUID().toString());}
 public static ResponseStatusException error(int status,String message){return new ResponseStatusException(HttpStatusCode.valueOf(status),message);}
 public static String digest(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public static String email(String value){if(value==null)throw error(422,"请检查输入信息及密码确认");String e=value.strip().toLowerCase(Locale.ROOT);if(e.length()>254||e.contains("..")||!e.matches("[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?\\.[A-Za-z]{2,63}"))throw error(422,"请检查输入信息及密码确认");return e;}
 public static void password(String p,String confirm){if(p==null||p.length()<8||p.length()>128||p.isBlank()||!p.equals(confirm))throw error(422,"请检查输入信息及密码确认");}
 public Map<String,Object> profile(Long id){return profile(users.findById(id).orElseThrow(()->error(401,"登录已过期，请重新登录")));}
 public Map<String,Object> profile(UserAccount u){Map<String,Object> result=new LinkedHashMap<>();result.put("id",u.getId());result.put("username",u.getUsername());result.put("email",u.getEmail());result.put("requiresSetup",u.isRequiresSetup());result.put("displayName",u.getDisplayName());result.put("roles",u.getRoles().stream().sorted().map(r->Map.of("authority",r)).toList());return result;}
 private String token(){byte[] b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
 public synchronized void budget(ServerWebExchange x,String namespace,String subject,int limit,int seconds,int ipLimit){String ip=x.getRequest().getRemoteAddress()==null?"unknown":x.getRequest().getRemoteAddress().getAddress().getHostAddress();tx.executeWithoutResult(status->records.deleteByExpiresAtBefore(Instant.now()));rate(namespace+":ip",ip,ipLimit,seconds);rate(namespace+":subject",subject,limit,seconds);}
 private void rate(String ns,String subject,int limit,int seconds){Boolean allowed;try{allowed=rateAttempt(ns,subject,limit,seconds);}catch(org.springframework.dao.DataIntegrityViolationException|org.springframework.orm.ObjectOptimisticLockingFailureException collision){allowed=rateAttempt(ns,subject,limit,seconds);}if(!Boolean.TRUE.equals(allowed))throw error(429,"请求过于频繁，请稍后再试");}
 private Boolean rateAttempt(String ns,String subject,int limit,int seconds){return tx.execute(s->{String key=digest("rate:"+ns+":"+subject+":"+(Instant.now().getEpochSecond()/seconds));AuthRecord row=records.locked(key).orElseGet(()->new AuthRecord(key));if(row.attempts>=limit)return false;row.attempts++;row.expiresAt=Instant.now().plusSeconds(seconds*2L);records.saveAndFlush(row);return true;});}
 public void basicFailure(ServerWebExchange x){String subject="unknown";try{String h=x.getRequest().getHeaders().getFirst("Authorization");String decoded=new String(Base64.getDecoder().decode(h.substring(6)),StandardCharsets.UTF_8);subject=decoded.split(":",2)[0];}catch(Exception ignored){}budget(x,"basic-login",subject,10,900,60);}
 public synchronized Map<String,Object> login(String username,String password,ServerWebExchange x){if(username==null||username.isBlank()||username.length()>254||password==null||password.isEmpty()||password.length()>128)throw error(422,"请检查输入信息及密码确认");String name=username.strip();budget(x,"password-login",name.contains("@")?name.toLowerCase(Locale.ROOT):name,10,900,60);UserAccount u=(name.contains("@")?users.findByEmail(name.toLowerCase(Locale.ROOT)):users.findByUsername(name)).orElse(null);boolean valid=encoder.matches(password,u==null?dummy:u.getPassword());if(!valid||u==null||!u.isEnabled())throw error(401,"用户名或密码错误");session(u,x);return profile(u);}
 public synchronized CurrentUser sessionUser(String raw){return tx.execute(s->{AuthRecord r=records.findById(digest(raw)).orElse(null);if(r==null||r.userId==null||r.expiresAt==null||!r.expiresAt.isAfter(Instant.now()))throw error(401,"登录已过期，请重新登录");UserAccount u=users.findById(r.userId).orElseThrow(()->error(401,"登录已过期，请重新登录"));if(!u.isEnabled())throw error(401,"登录已过期，请重新登录");return new CurrentUser(u);});}
 private void session(UserAccount u,ServerWebExchange x){String raw=token();tx.executeWithoutResult(s->{UserAccount current=users.lockById(u.getId()).orElseThrow(()->error(401,"登录已过期，请重新登录"));if(!current.isEnabled()||!Objects.equals(current.getPassword(),u.getPassword()))throw error(409,"账号凭据已更新，请重新登录");var old=x.getRequest().getCookies().getFirst(COOKIE);if(old!=null)records.deleteById(digest(old.getValue()));AuthRecord r=new AuthRecord(digest(raw));r.userId=u.getId();r.expiresAt=Instant.now().plusSeconds(28800);records.save(r);});cookie(x,raw,28800);}
 private void cookie(ServerWebExchange x,String raw,int age){x.getResponse().addCookie(ResponseCookie.from(COOKIE,raw).httpOnly(true).secure("https".equals(x.getRequest().getURI().getScheme())).sameSite("Lax").path("/").maxAge(age).build());x.getResponse().getHeaders().setCacheControl("no-store");}
 public synchronized Map<String,String> logout(ServerWebExchange x){var c=x.getRequest().getCookies().getFirst(COOKIE);if(c!=null)tx.executeWithoutResult(s->records.deleteById(digest(c.getValue())));cookie(x,"",0);return Map.of("message","已退出登录");}
 private boolean student(UserAccount u){return u!=null&&u.isEnabled()&&u.getRoles().equals(Set.of("ROLE_USER"));}
 private boolean registration(){return !Set.of("online","light").contains(env.getProperty("mindbridge.runtime.profile","offline"));}
 public Map<String,Object> sendCode(String target,ServerWebExchange x){String e=email(target);budget(x,"send-code",e,6,3600,30);UserAccount u=users.findByEmail(e).orElse(null);if(student(u)||(u==null&&registration()))deliver(e,"login");return Map.of("message","如邮箱可用于学生登录，验证码将发送至该邮箱","resendAfter",60,"expiresIn",300);}
 private void deliver(String e,String purpose){String code=String.format(Locale.ROOT,"%06d",random.nextInt(1000000));String key=digest("code:"+purpose+":"+e);tx.executeWithoutResult(s->{AuthRecord r=records.locked(key).orElseGet(()->new AuthRecord(key));if(r.sentAt!=null&&r.sentAt.isAfter(Instant.now().minusSeconds(60)))throw error(429,"请等待60秒后重新发送验证码");r.value=encoder.encode(code);r.sentAt=Instant.now();r.expiresAt=Instant.now().plusSeconds(300);r.attempts=0;r.consumed=false;records.saveAndFlush(r);});try{if(!"smtp".equalsIgnoreCase(properties.getMcp().getEmail().getMode())||!(env.getProperty("spring.mail.properties.mail.smtp.ssl.enable",Boolean.class,false)||env.getProperty("spring.mail.properties.mail.smtp.starttls.required",Boolean.class,false)))throw new IllegalStateException();SimpleMailMessage message=new SimpleMailMessage();message.setFrom(properties.getMcp().getEmail().getFrom());message.setTo(e);message.setSubject("[SolaceAI] 验证码");message.setText("您的验证码为："+code+"\n验证码有效期为5分钟，请勿向他人透露。");mail.send(message);}catch(Exception ex){tx.executeWithoutResult(s->{AuthRecord r=records.locked(key).orElseThrow();r.consumed=true;records.save(r);});throw error(503,"邮件服务暂不可用，请稍后重试");}}
 private void consume(String e,String purpose,String code){if(code==null||!code.matches("[0-9]{6}"))throw error(422,"请检查输入信息及密码确认");boolean valid=Boolean.TRUE.equals(tx.execute(s->{AuthRecord r=records.locked(digest("code:"+purpose+":"+e)).orElse(null);if(r==null||r.consumed||r.attempts>=5||!r.expiresAt.isAfter(Instant.now()))return false;r.attempts++;boolean ok=encoder.matches(code,r.value);if(ok)r.consumed=true;records.saveAndFlush(r);return ok;}));if(!valid)throw error(401,"验证码无效或已过期");}
 public synchronized Map<String,Object> emailLogin(String target,String code,ServerWebExchange x){String e=email(target);budget(x,"email-login",e,15,900,60);consume(e,"login",code);UserAccount u=users.findByEmail(e).orElse(null);if(u==null){if(!registration())throw error(403,"根据有关要求暂不开放注册，实际账号体验请联系管理员。");u=new UserAccount();u.setUsername("student_"+UUID.randomUUID().toString().replace("-",""));u.setEmail(e);u.setDisplayName("新同学");u.setRequiresSetup(true);u.setPassword(encoder.encode(token()));u.setRoles(Set.of("ROLE_USER"));u=users.saveAndFlush(u);}if(!student(u))throw error(401,"验证码无效或已过期");session(u,x);return profile(u);}
 public synchronized Map<String,Object> setup(Long id,String name,String p,String confirm,ServerWebExchange x){password(p,confirm);if(name==null||!name.matches("[A-Za-z0-9_-]{3,64}"))throw error(422,"请检查输入信息及密码确认");budget(x,"setup",id.toString(),10,900,60);UserAccount u=tx.execute(s->{UserAccount v=users.lockById(id).orElseThrow();if(!v.isRequiresSetup())throw error(409,"账号已完成设置");if(users.findByUsername(name).filter(other->!other.getId().equals(id)).isPresent())throw error(409,"用户名或邮箱已被使用");v.setUsername(name);v.setPassword(encoder.encode(p));v.setRequiresSetup(false);if("新同学".equals(v.getDisplayName()))v.setDisplayName(name);records.deleteByUserId(id);return users.saveAndFlush(v);});session(u,x);return profile(u);}
 public synchronized Map<String,Object> changePassword(Long id,String current,String p,String confirm,ServerWebExchange x){password(p,confirm);budget(x,"change-password",id.toString(),5,900,60);UserAccount u=tx.execute(s->{UserAccount v=users.lockById(id).orElseThrow();requirePassword(v,current);v.setPassword(encoder.encode(p));records.deleteByUserId(id);return users.saveAndFlush(v);});session(u,x);return profile(u);}
 private void requirePassword(UserAccount u,String current){if(current==null||current.length()>128||!encoder.matches(current,u.getPassword()))throw error(401,"原密码不正确");}
 private void binding(UserAccount u,String e,String current){requirePassword(u,current);if(u.getEmail()!=null)throw error(409,"账号已绑定邮箱");if(users.findByEmail(e).isPresent())throw error(409,"用户名或邮箱已被使用");}
 public Map<String,Object> bindCode(Long id,String target,String current,ServerWebExchange x){String e=email(target);budget(x,"bind-code-user",id.toString(),6,3600,30);budget(x,"bind-code-email",e,6,3600,30);binding(users.findById(id).orElseThrow(),e,current);deliver(e,"b"+id);return Map.of("resendAfter",60,"expiresIn",300);}
 public synchronized Map<String,Object> bind(Long id,String target,String current,String code,ServerWebExchange x){String e=email(target);budget(x,"bind-email",id.toString(),10,900,60);binding(users.findById(id).orElseThrow(),e,current);consume(e,"b"+id,code);UserAccount u=tx.execute(s->{UserAccount v=users.lockById(id).orElseThrow();binding(v,e,current);v.setEmail(e);return users.saveAndFlush(v);});x.getResponse().getHeaders().setCacheControl("no-store");return profile(u);}
}
